#pragma once
#include "radio_v3.h"
struct HubPeer{uint8_t mac[6],key[16];uint32_t boot=0,seen=0,sequence=0;RadioFrame state;String pending[4],device[4],actor[4];uint32_t pendingAt[4]={};};
struct HubRx{uint8_t mac[6];RadioFrame frame;};
HubPeer hubPeers[6];int hubCount=0;QueueHandle_t hubQueue=nullptr;uint32_t hubBoot=0;
void hubReceive(const uint8_t*mac,const uint8_t*raw,int length){if(length!=sizeof(RadioFrame)||!hubQueue)return;HubRx rx;memcpy(rx.mac,mac,6);memcpy(&rx.frame,raw,length);for(int i=0;i<hubCount;i++)if(!memcmp(mac,hubPeers[i].mac,6)&&radioValid(rx.frame,hubPeers[i].key)){rx.frame.command[36]=0;rx.frame.counterEpoch[32]=0;xQueueSend(hubQueue,&rx,0);break;}}
void hubBegin(){
#if NX_HUB
 hubQueue=xQueueCreate(8,sizeof(HubRx));hubBoot=esp_random();if(!hubQueue||esp_now_init()!=ESP_OK)return;DynamicJsonDocument d(4096);if(deserializeJson(d,prefs.getString("radio","{}")))return;uint8_t pmk[16];if(!unhex(d["pmk"].as<String>(),pmk,16))return;esp_now_set_pmk(pmk);for(JsonObject p:d["peers"].as<JsonArray>()){if(hubCount>=6)break;auto&peer=hubPeers[hubCount];if(!parseMac(p["mac"].as<String>(),peer.mac)||!unhex(p["lmk"].as<String>(),peer.key,16))continue;if(addEncryptedPeer(peer.mac,peer.key))hubCount++;}esp_now_register_recv_cb(hubReceive);
#endif
}
HubPeer* hubPeer(JsonObject n){uint8_t mac[6];if(!parseMac(n["mac"].as<String>(),mac))return nullptr;for(int i=0;i<hubCount;i++)if(!memcmp(mac,hubPeers[i].mac,6))return &hubPeers[i];return nullptr;}
bool hubPulse(JsonObject n,const String&cmd,const String&actor,uint32_t expires){auto*p=hubPeer(n);int ch=n["channel"]|1;if(!p||!p->boot||millis()-p->seen>7000||ch<1||ch>4||p->pending[ch-1].length()||!(p->state.outputs&(1<<(ch-1)))||time(nullptr)<1700000000)return false;RadioFrame f;f.type=R_PULSE;f.senderBoot=hubBoot;f.targetBoot=p->boot;f.sequence=++p->sequence;f.channel=ch;f.pulseMs=n["pulseMs"]|1000;f.expires=expires?min(expires,(uint32_t)time(nullptr)+6):(uint32_t)time(nullptr)+6;if(f.expires<=time(nullptr))return false;strlcpy(f.command,cmd.c_str(),37);radioSign(f,p->key);if(esp_now_send(p->mac,(uint8_t*)&f,sizeof(f))!=ESP_OK)return false;p->pending[ch-1]=cmd;p->device[ch-1]=n["id"].as<String>();p->actor[ch-1]=actor;p->pendingAt[ch-1]=millis();return true;}
void hubTick(){if(!hubQueue)return;HubRx rx;while(xQueueReceive(hubQueue,&rx,0)==pdTRUE)for(int i=0;i<hubCount;i++){auto&p=hubPeers[i];if(memcmp(p.mac,rx.mac,6))continue;const auto&f=rx.frame;if(f.type!=R_STATUS&&f.type!=R_ACK)continue;p.seen=millis();p.boot=f.senderBoot;p.state=f;RadioFrame hello;hello.type=R_HELLO;hello.senderBoot=hubBoot;hello.targetBoot=p.boot;hello.expires=time(nullptr);radioSign(hello,p.key);esp_now_send(p.mac,(uint8_t*)&hello,sizeof(hello));int ch=int(f.channel)-1;if(f.type==R_ACK&&ch>=0&&ch<4&&p.pending[ch].length()&&p.pending[ch]==String(f.command)){if(results.size()<10){auto r=results.as<JsonArray>().createNestedObject();r["id"]=p.pending[ch];r["status"]=f.success?"executed":"failed";r["message"]=f.success?"Escravo confirmou o fim do pulso; consulte o reed":"Escravo recusou o comando";}localEvent(p.actor[ch],"Acionamento",p.device[ch],f.success?"Pulso confirmado pelo escravo":"Comando recusado pelo escravo");p.pending[ch]="";}}
for(int i=0;i<hubCount;i++){auto&p=hubPeers[i];for(int ch=0;ch<4;ch++)if(p.pending[ch].length()&&millis()-p.pendingAt[ch]>7000){if(results.size()<10){auto r=results.as<JsonArray>().createNestedObject();r["id"]=p.pending[ch];r["status"]="unknown";r["message"]="Sem confirmacao do escravo. Nao repetir automaticamente.";}p.pending[ch]="";}}}
